const person = $items("FUB - Get Person")[0]?.json?.people?.[0] || {};
const settingsRows = $items("Read Settings").map(i => i.json || {});
const identityRows = $items("Read Identity Verifications").map(i => i.json || {});
const originalBody = $("Webhook").first().json.body || {};

const settings = {};
for (const row of settingsRows) {
  if (row.key && row.value !== undefined) settings[row.key] = row.value;
}

const rejectedLabel = (settings.rejected_stage_label || "Rejected").trim().toLowerCase();
const stage = (person.stage || "").trim();
const phone = person.phones?.[0]?.value;

function fail(reason) {
  return [{ json: {
    proceed: false, reason,
    person_id: person.id ? String(person.id) : "",
    person_name: person.name || "",
  } }];
}

// Same safeguard as the existing SMS workflow: only proceed for synthetic
// test leads until this is validated end-to-end on real applicants.
const isTestMode = (person.firstName || "") === "Test";
if (!isTestMode) return fail("not_test_mode");

if (!phone) return fail("no_phone");

// ── TRASH_TAG_GATE_MARKER: tag-based trash gate (replaces the old stage=="trash" check) ──
// See docs/n8n-workflows.md "FUB Trash-tag gate".
// Reroute PATCH + marker note happen downstream of "Should Proceed?" (false
// branch) -> "Needs Reapply Reroute?", not here — this node only decides.
const tagsLower = (person.tags || []).map((t) => String(t).trim().toLowerCase());
const trashDateMs = new Date(person.customTrashDate || "").getTime();
const daysSinceTrash = Number.isFinite(trashDateMs) ? (Date.now() - trashDateMs) / 86400000 : Infinity;
let trashBlock = null;
if (tagsLower.includes("permanent trash")) trashBlock = { reason: "trash_permanent", rerouteStage: "Permanent Trash" };
else if (tagsLower.includes("denied credit")) { if (daysSinceTrash <= 365) trashBlock = { reason: "trash_denied_credit", rerouteStage: "Cold Rental Lead 1 month Hold" }; }
else if (tagsLower.includes("temporary trash")) { if (daysSinceTrash <= 90) trashBlock = { reason: "trash_temporary", rerouteStage: "Trash" }; }
// ── TRASH_FALLTHROUGH_MARKER: the stage fallback must run whenever no TAG produced a
// block -- as an "else if" it was skipped by any matching tag, so a
// dateless/expired tag left someone LESS protected than an untagged
// person. See scripts/n8n-add-trash-fallthrough.mjs.
if (!trashBlock && ["trash", "permanent trash", "cold rental lead 1 month hold"].includes(stage.toLowerCase())) trashBlock = { reason: "trash_untagged_fallback", rerouteStage: null };
// ── TAG_EXPIRY_CLEANUP_MARKER: strip a trash tag whose window has provably expired ──────
// All three tags share ONE customTrashDate (the most recent transition), so
// a stale tag riding alongside a fresh one silently wins the precedence rule
// -- Denied Credit would give 365 days and reroute to Cold Hold when the real
// event was a 90-day Trash. Precedence logic can't tell them apart; removing
// the expired tag while it IS still expired is the only point where we can.
// Permanent Trash has no window and is never removed. A tag with no real
// date is left alone: Infinity days reads as "expired", but the absence of
// OUR field is not evidence about the CLIENT's tag.
const TAG_WINDOW_DAYS = { "temporary trash": 90, "denied credit": 365 };
const hasRealTrashDate = Number.isFinite(trashDateMs);
const expiredTags = hasRealTrashDate
  ? (person.tags || []).filter((t) => {
      const w = TAG_WINDOW_DAYS[String(t).trim().toLowerCase()];
      return w !== undefined && daysSinceTrash > w;
    })
  : [];
const cleanedTags = (person.tags || []).filter((t) => !expiredTags.includes(t));
const needsTagCleanup = expiredTags.length > 0;

if (trashBlock) {
  const needsReapplyReroute = !!trashBlock.rerouteStage && stage.toLowerCase() !== trashBlock.rerouteStage.toLowerCase();
  return [{ json: {
    proceed: false, reason: trashBlock.reason,
    person_id: person.id ? String(person.id) : "",
    person_name: person.name || "",
    needs_reapply_reroute: needsReapplyReroute,
    reapply_reroute_stage: trashBlock.rerouteStage || "",
    reapply_preserved_trash_date: person.customTrashDate || "",
    needs_tag_cleanup: needsTagCleanup,
    expired_tags: expiredTags,
    cleaned_tags: cleanedTags,
    trash_date: person.customTrashDate || "",
  } }];
}

if (stage.toLowerCase() === rejectedLabel) return fail("rejected_stage");

// ── STAGE_GATE_MARKER: FUB stage gate ────────────────────────────────────────────
// A lead outside the allowed stages never gets a verification SMS.
// Empty / missing allowed_stages == allow everything, so losing the Settings
// row degrades to the pre-gate behaviour rather than muting the whole system.
const allowedStages = String(settings.allowed_stages ?? "")
  .split(",")
  .map((s) => s.trim().toLowerCase())
  .filter(Boolean);
// Sheets coerces on write and the stage names contain punctuation and mixed
// case ("Tenant Inquiry Lead (Do Not Contact)"), so compare normalized.
const personStage = String(person.stage ?? "").trim().toLowerCase();
const stageAllowed = allowedStages.length === 0 || allowedStages.includes(personStage);

if (!stageAllowed) return fail("stage_not_allowed:" + stage);


// Test-mode leads are reused indefinitely for end-to-end testing, so
// don't let a prior session block a fresh test run.
const alreadySent = identityRows.some(r => String(r.lead_id) === String(person.id));
if (!isTestMode && alreadySent) return fail("already_sent");

// ── PENDING_VERIFICATION_GUARD_MARKER ────────────────────────────────────────────────────────────
// A second inquiry from the same lead while their first verification session
// is still open must not fire a second Stripe session / second SMS — the
// Inquiry flow calls this gate on every inquiry from an unverified lead by
// design, so THIS is the place that has to be safe to call more than once.
// Applies to test leads too (this is exactly how the bug was found).
// Matched on person_id OR phone (last 10 digits — formats vary: FUB stores
// bare digits, the sheet/Twilio store "+1..."), same discipline as the
// Inquiry flow's identity lookup. A pending row older than the TTL is
// treated as abandoned, not "in flight", so a lead who never finished
// Stripe Identity isn't stuck forever.
const pendingTtlHours = Number(settings.identity_verification_pending_ttl_hours ?? 24) || 24;
const last10 = (v) => String(v ?? "").replace(/\D/g, "").slice(-10);
const personLast10 = last10(phone);
const nowMs = Date.now();
const hasPendingSession = identityRows.some(r => {
  const sameLead = String(r.lead_id ?? "") !== "" && String(r.lead_id) === String(person.id ?? "");
  const samePhone = personLast10 !== "" && last10(r.phone) === personLast10;
  if (!(sameLead || samePhone)) return false;
  if (String(r.status ?? "").trim().toLowerCase() !== "pending") return false;
  const sentMs = new Date(r.sent_at).getTime();
  // Unparseable sent_at can't be judged stale — treat as still in flight
  // rather than risk letting a second SMS through.
  const ageHours = Number.isFinite(sentMs) ? (nowMs - sentMs) / 3600000 : 0;
  return ageHours < pendingTtlHours;
});
if (hasPendingSession) return fail("verification_already_pending");

const digits = phone.replace(/\D/g, "");
const toNumber = digits.length === 10 ? `+1${digits}` : `+${digits}`;

return [{ json: {
  proceed: true,
  reason: "ok",
  person_id: String(person.id),
  person_name: person.name || "",
  first_name: person.firstName || person.name || "",
  email: person.emails?.[0]?.value || undefined,
  stage,
  phone: toNumber,
  from_number: settings.from_number || "",
  identity_sms_template: settings.identity_verification_sms_template || "",
  original_webhook_body: JSON.stringify(originalBody),
  needs_tag_cleanup: needsTagCleanup,
  expired_tags: expiredTags,
  cleaned_tags: cleanedTags,
  trash_date: person.customTrashDate || "",
} }];

const guard = $("Check Guards").first().json;
const session = $json;

const template = guard.identity_sms_template ||
  "Hi {{first_name}}, before we can schedule your showing we need to quickly verify your ID. Please complete this short verification: {{verify_link}}";

const message = template
  .replace(/\{\{first_name\}\}/g, guard.first_name || "")
  .replace(/\{\{verify_link\}\}/g, session.url || "");

return [{ json: {
  message,
  phone: guard.phone,
  from_number: guard.from_number,
  session_id: session.sessionId,
  person_id: guard.person_id,
  person_name: guard.person_name,
  original_webhook_body: guard.original_webhook_body,
  sent_at: new Date().toISOString(),
} }];

// ── TRASH_TAG_GATE_MARKER: stage-transition watcher, stamps customTrashDate ──
// FUB's peopleUpdated webhook carries no previous-stage data (confirmed live,
// 2026-08-06/07 against real executions) -- customTrashGateLastStage is our
// own cache of "what stage did we last see this person in", written by this
// node. A transition is "entering a trash-family stage the cache didn't
// already show them in". See docs/n8n-workflows.md "FUB Trash-tag gate".
const personPayload = $items("FUB - Get Person")[0]?.json || {};
const person = personPayload.people?.[0] || personPayload;
// ── WATCHER_ISOLATION_MARKER: the notes fetch is allowed to fail without aborting this
// workflow (onError: continueRegularOutput), so it can hand us an { error }
// item instead of notes. We cannot check for the reapply self-collision
// marker in that case -- so do NOT stamp customTrashDate on an unverified
// basis. Refreshing the cache field is still safe and keeps future
// comparisons accurate. See docs/n8n-workflows.md "Watcher isolation".
const notesPayload = $items("FUB - Get Recent Notes")[0]?.json || {};
const notesUnavailable = !!notesPayload.error || !Array.isArray(notesPayload.notes);
const recentNotes = Array.isArray(notesPayload.notes) ? notesPayload.notes : [];

const TRASH_STAGES = ["trash", "permanent trash", "cold rental lead 1 month hold"];
const currentStage = String(person.stage ?? "").trim();
const currentStageLower = currentStage.toLowerCase();
const cachedStage = String(person.customTrashGateLastStage ?? "").trim();
const cachedStageLower = cachedStage.toLowerCase();

const cacheStale = cachedStageLower !== currentStageLower;

// ── WATCHER_SCOPE_MARKER: only act on the two gated tenant stages ──────────────
// The client's FUB account is not only a rental CRM (owners, lenders,
// developers, general contacts also live in it). Client decision 2026-08-07:
// this watcher must not write to those people at all. Hardcoded rather than
// read from Settings' allowed_stages because this node runs BEFORE
// Read Settings -- see scripts/n8n-add-watcher-scope.mjs for the full
// rationale. Keep in sync with the production allowed_stages value.
const WATCH_SCOPE_STAGES = [
  "tenant inquiry lead (do not contact)",
  "tenant still looking for rental",
];
const inScope = WATCH_SCOPE_STAGES.includes(currentStageLower);
const cachedInScope = WATCH_SCOPE_STAGES.includes(cachedStageLower);
const inTrashFamily = TRASH_STAGES.includes(currentStageLower);
